import{_ as e}from"./chunks/dtc-editor.DKK7pOGa.js";import{_ as r,o,c as a,a3 as n}from"./chunks/framework.B9qR_F1m.js";const m=JSON.parse('{"title":"DTC – Cartridges","description":"","frontmatter":{},"headers":[],"relativePath":"en/dtc.md","filePath":"en/dtc.md"}'),i={name:"en/dtc.md"};function s(d,t,h,l,g,c){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="dtc-–-cartridges" tabindex="-1">DTC – Cartridges <a class="header-anchor" href="#dtc-–-cartridges" aria-label="Permalink to &quot;DTC – Cartridges&quot;">​</a></h1><p>Since DCS introduced the <strong>Data Transfer Cartridge</strong>, the jet loads steerpoints, radios and countermeasures from a file. Shardwing builds these cartridges for the <strong>F-16C</strong> and <strong>F/A-18C</strong> – in the native DCS format, as if they came from the Mission Editor&#39;s DTC manager.</p><p><img src="'+e+'" alt="DTC editor of an F-16C with steerpoints, targets and threat rings on the map" loading="lazy"></p><h2 id="creating-a-cartridge" tabindex="-1">Creating a cartridge <a class="header-anchor" href="#creating-a-cartridge" aria-label="Permalink to &quot;Creating a cartridge&quot;">​</a></h2><p>Tab <strong>DTC</strong> of a flight:</p><table tabindex="0"><thead><tr><th>Button</th><th>What happens</th></tr></thead><tbody><tr><td><strong>Neu aus Route</strong> (new from route)</td><td>Takes over the waypoints as steerpoints, the radio presets and <strong>only the threats released to this flight</strong>. CMDS stays with the pilot by default. The usual choice.</td></tr><tr><td><strong>Neu leer</strong> (new, empty)</td><td>An empty cartridge – with radios, CMDS and switches from your default cartridge, if you have set one.</td></tr><tr><td><strong>Aus Datei …</strong> (from file)</td><td>Load an existing <code>.dtc</code>, e.g. your own from <code>Saved Games\\DCS\\DTC</code>.</td></tr></tbody></table><p>A cartridge in the mission is a <strong>file inside the .miz</strong>. It is attached to one or more aircraft; the editor&#39;s header shows which ones (<em>an Aerial-1</em>, i.e. &quot;on Aerial-1&quot;). Several flights can share one cartridge.</p><h2 id="the-editor-s-header" tabindex="-1">The editor&#39;s header <a class="header-anchor" href="#the-editor-s-header" aria-label="Permalink to &quot;The editor&#39;s header&quot;">​</a></h2><ul><li><strong>Name</strong> – becomes the file name inside the .miz.</li><li><strong>an …</strong> (on …) – which units of the flight load the cartridge.</li><li><strong>AutoLoad</strong> – loads automatically on spawn. Without AutoLoad, the pilot loads it on the DTE page (F-16) or MUMI page (F/A-18).</li><li><strong>Als meine Standard-Cartridge</strong> (as my default cartridge) – the radios, CMDS and switches of this cartridge become the template for <em>Neu leer</em> (without waypoints, lines, threats).</li><li><strong>.dtc exportieren</strong> (export .dtc) – save as a single file, e.g. for <code>Saved Games\\DCS\\DTC</code>.</li><li><strong>Entfernen</strong> (remove) – take the cartridge out of the mission.</li></ul><h2 id="sections-and-overwrite" tabindex="-1">Sections and &quot;overwrite&quot; <a class="header-anchor" href="#sections-and-overwrite" aria-label="Permalink to &quot;Sections and &quot;overwrite&quot;&quot;">​</a></h2><p>A cartridge consists of sections (NAV, COMM, CMDS …). Each section has the switch <strong>überschreiben</strong> (overwrite):</p><ul><li><strong>on</strong> – written into the jet when loading.</li><li><strong>off</strong> – left out of the .dtc; the jet keeps what it has.</li></ul><p>This way you can set steerpoints and radios but <strong>leave the pilot&#39;s CMDS programs untouched</strong>.</p><p><strong>Übernehmen aus …</strong> (take from …) copies a section from another cartridge – your own CMDS programs, for example.</p><h2 id="f-16c" tabindex="-1">F-16C <a class="header-anchor" href="#f-16c" aria-label="Permalink to &quot;F-16C&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Section</th><th>Steerpoints</th><th>Content</th></tr></thead><tbody><tr><td><strong>NAV</strong></td><td>1–24</td><td>Steerpoints with coordinates, elevation, TOS, offset aimpoints (OA1/OA2), assignment to routes 1–3. Steerpoint 25 is the bullseye.</td></tr><tr><td><strong>Geo Lines</strong></td><td>31–55</td><td>Lines on the HSD – taken over from drawings (FLOT, kill box, CAP …) or placed by hand, up to four lines.</td></tr><tr><td><strong>Threats</strong></td><td>56–70</td><td>Threat rings with DCS type and range – released ones only. <strong>Von Intel übernehmen</strong> (take from intel) adds the released threats near the route that are still missing. Pick the <strong>type</strong> from SA-2, SA-3, SA-5, SA-6, SA-11 or <em>Custom</em>; a type brings the Mission Editor&#39;s ring and HSD text with it.</td></tr><tr><td><strong>DEST</strong></td><td>81–99</td><td>Destination points, e.g. airfields.</td></tr><tr><td><strong>VIP/VRP</strong></td><td>1 each</td><td>Visual initial point or visual reference point with bearing/distance/elevation to target and PUP.</td></tr><tr><td><strong>COMM</strong></td><td>–</td><td>COMM1 (UHF) and COMM2 (VHF/FM), 20 presets per radio.</td></tr><tr><td><strong>CMDS</strong></td><td>–</td><td>Chaff/flare programs. Default: <em>don&#39;t overwrite</em>.</td></tr></tbody></table><h3 id="editing-steerpoints" tabindex="-1">Editing steerpoints <a class="header-anchor" href="#editing-steerpoints" aria-label="Permalink to &quot;Editing steerpoints&quot;">​</a></h3><ul><li><strong>Click on the map</strong> to place a new steerpoint, drag to move it. When the list is full (e.g. 24 NAV points), placing on the map stops by itself.</li><li>In the table: type, note, coordinates, <strong>Elev ft</strong>, <strong>TOS</strong>, OA1/OA2 and the routes (1, 2, 3 – as in the DTC manager).</li><li><strong>Elev = Boden (alle)</strong> (elevation = ground, all) sets the elevation of every point from terrain data (SRTM, may differ from DCS by a few metres).</li><li><strong>TOS verschieben</strong> (shift TOS) by ±1 or ±5 minutes; <strong>TOS aus Route</strong> (TOS from route) takes over the ETAs of the mission route. TOS is stored in Zulu; <kbd>↑</kbd>/<kbd>↓</kbd> in the time field changes the digit under the cursor, with <kbd>Shift</kbd> in steps of ten.</li><li><strong>⌖ auf …</strong> (onto …) below the coordinates puts the steerpoint on a place the designer has set: your target times with a location, the tanker track and, under <em>Weitere Planungspunkte</em> (more planning points), every planning point of your side (fix, RV, CP …), even without a time for your flight. That way you place shared waypoints without typing coordinates.</li><li>Arrows ↑ ↓ change the order, × deletes.</li></ul><h3 id="times-flight-plan-or-on-their-own" tabindex="-1">Times: flight plan or on their own <a class="header-anchor" href="#times-flight-plan-or-on-their-own" aria-label="Permalink to &quot;Times: flight plan or on their own&quot;">​</a></h3><p>The steerpoint times (TOS, ETA on the F/A-18C) come from the flight plan on the <strong>Route</strong> tab. A new cartridge is coupled to it: the time column here only shows them, and on saving or exporting the .dtc the plan&#39;s times are written into the cartridge.</p><p>The switch <strong>Zeiten getrennt planen</strong> (plan times separately) cuts that link: you type the times here and the flight plan leaves them alone. Cartridges from a file or from the mission start out separate; <strong>An den Flugplan koppeln</strong> on the Route tab couples them.</p><h3 id="geo-lines-from-drawings" tabindex="-1">Geo lines from drawings <a class="header-anchor" href="#geo-lines-from-drawings" aria-label="Permalink to &quot;Geo lines from drawings&quot;">​</a></h3><p><strong>Aus Grafik übernehmen …</strong> / <strong>Aus Zeichnung übernehmen</strong> (take from graphic / drawing) turns a FLOT, kill box or CAP station into a geo line – into the next free line or appended to a specific one. Areas are closed, racetracks are stepped.</p><h2 id="f-a-18c" tabindex="-1">F/A-18C <a class="header-anchor" href="#f-a-18c" aria-label="Permalink to &quot;F/A-18C&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Section</th><th>Content</th></tr></thead><tbody><tr><td><strong>Waypoints</strong></td><td>1–59, route 1</td></tr><tr><td><strong>SA page</strong></td><td>CAP points (racetrack with anchor, course, leg, turn left/right), FLOT, FAOR and corridor, MEZ rings (threats; <strong>Von Intel übernehmen</strong> appends the threats released to the flight near its route)</td></tr><tr><td><strong>COMM</strong></td><td>Presets with channel names that appear on the UFC. The Hornet takes UHF and VHF on both radios.</td></tr><tr><td><strong>TACAN</strong></td><td>The jet&#39;s station list: ident, channel (band X), name, elevation, coordinate. <strong>Station der Karte anhängen</strong> adds a ground station of the DCS map. Without &quot;überschreiben&quot; the jet keeps its own list.</td></tr><tr><td><strong>CMDS</strong></td><td>ALR-67 programs</td></tr></tbody></table><h2 id="comm" tabindex="-1">COMM <a class="header-anchor" href="#comm" aria-label="Permalink to &quot;COMM&quot;">​</a></h2><p>Any station on any channel, in the band of your choice. The F-16 only takes UHF on COMM1 and VHF/FM on COMM2; the Hornet takes both. Easier than channel by channel: set up the package-wide comm plan under <strong>Kneeboards → Comm Plan</strong> and apply it to all cartridges with one button.</p><h2 id="personal-cartridges" tabindex="-1">Personal cartridges <a class="header-anchor" href="#personal-cartridges" aria-label="Permalink to &quot;Personal cartridges&quot;">​</a></h2><p>When planning together, several aircraft often share a cartridge. If a pilot changes <strong>their CMDS or colours</strong>, Shardwing creates a personal copy (<code>&lt;cartridge&gt; - &lt;callsign&gt;</code>). Their jet loads the copy, everyone else keeps the shared one. A cartridge loaded by several flights can only be changed by the designer – a flight can make its own copy.</p><h2 id="single-cartridges" tabindex="-1">Single cartridges <a class="header-anchor" href="#single-cartridges" aria-label="Permalink to &quot;Single cartridges&quot;">​</a></h2><p>If you open a <code>.dtc</code> file without a mission, it appears on the left under <strong>Einzelne Cartridges</strong> (single cartridges). You can edit it and save it as a <code>.dtc</code> again – your personal default cartridge, for example.</p>',31)])])}const f=r(i,[["render",s]]);export{m as __pageData,f as default};
